<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();api_rate_limit($user,'notifications.list',60,60);$stmt=db()->prepare("SELECT id,type,channel,title,message,status,created_at,sent_at FROM notifications WHERE (user_id=? OR user_id IS NULL) AND channel IN ('IN_APP','PUSH') ORDER BY id DESC LIMIT 100");$stmt->execute([$user['id']]);json_response(true,'Notifications retrieved',$stmt->fetchAll());
